//! Canonical contract for reusable local calibration evidence.
//!
//! Every producer and consumer uses this module. Older schemas are not
//! upgraded in memory: they must be regenerated by the current calibrator.

use anyhow::{Result, ensure};
use serde_json::Value;

pub const CALIBRATION_RECEIPT_SCHEMA: &str = crate::project_identity::CALIBRATION_RECEIPT_SCHEMA;
pub const CALIBRATION_RECEIPT_STATUS: &str = "measured-sustained-execution";
pub const LOGICAL_REPLAY_SNAPSHOT_KIND: &str = "logical-replay-token-history";
pub const PHYSICAL_COLDSTORE_SNAPSHOT_KIND: &str = "physical-coldstore-handle";

pub fn validate_calibration_receipt(receipt: &Value, expected_bundle: &str) -> Result<()> {
    ensure!(
        is_sha256(expected_bundle),
        "expected bundle is not a SHA-256 digest"
    );
    ensure!(
        receipt.get("project").and_then(Value::as_str) == Some(crate::project_identity::PROJECT)
            && receipt.get("product").and_then(Value::as_str)
                == Some(crate::project_identity::PRODUCT)
            && receipt.get("technical_namespace").and_then(Value::as_str)
                == Some(crate::project_identity::TECHNICAL_NAMESPACE),
        "unsupported calibration receipt project identity"
    );
    ensure!(
        receipt.get("schema").and_then(Value::as_str) == Some(CALIBRATION_RECEIPT_SCHEMA),
        "unsupported calibration receipt schema"
    );
    ensure!(
        receipt.get("status").and_then(Value::as_str) == Some(CALIBRATION_RECEIPT_STATUS),
        "calibration receipt is not a sustained measurement"
    );
    ensure!(
        receipt.get("bundle").and_then(Value::as_str) == Some(expected_bundle),
        "calibration receipt belongs to another bundle"
    );
    ensure!(
        crate::build_info::is_current_clean_source_revision(receipt.get("source_revision")),
        "calibration receipt belongs to another or dirty source revision"
    );
    ensure!(
        receipt
            .get("identity_digest")
            .and_then(Value::as_str)
            .is_some_and(is_sha256),
        "calibration identity digest is invalid"
    );
    let adapter = receipt
        .get("adapter")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| anyhow::anyhow!("calibration adapter is missing"))?;
    ensure!(
        receipt
            .get("started_unix_seconds")
            .and_then(Value::as_u64)
            .is_some_and(|value| value > 0),
        "calibration start timestamp is invalid"
    );
    let measured_runs = bounded(receipt, "measured_runs", 3, 20)?;
    let decode_tokens = bounded(receipt, "decode_tokens_per_run", 8, 512)?;
    ensure!(
        receipt
            .get("warmup_runs")
            .and_then(Value::as_u64)
            .is_some_and(|value| (1..=10).contains(&value)),
        "calibration warmup count is invalid"
    );

    let expected_gate = if adapter == "accelerator-runtime" {
        "same-backend-and-kv-integrity-passed"
    } else {
        "not-required-for-non-accelerator"
    };
    ensure!(
        receipt
            .get("validation_matrix_gate")
            .and_then(Value::as_str)
            == Some(expected_gate),
        "calibration validation-matrix gate is invalid for the selected adapter"
    );

    let snapshot = receipt
        .get("snapshot_contract")
        .and_then(Value::as_object)
        .ok_or_else(|| anyhow::anyhow!("calibration snapshot contract is missing"))?;
    let (expected_snapshot_kind, expected_physical_persistence) =
        if adapter == "accelerator-runtime" {
            (PHYSICAL_COLDSTORE_SNAPSHOT_KIND, true)
        } else {
            (LOGICAL_REPLAY_SNAPSHOT_KIND, false)
        };
    ensure!(
        snapshot.get("kind").and_then(Value::as_str) == Some(expected_snapshot_kind),
        "unsupported calibration snapshot kind for the selected adapter"
    );
    ensure!(
        snapshot
            .get("physical_kv_persisted")
            .and_then(Value::as_bool)
            == Some(expected_physical_persistence),
        "calibration snapshot persistence does not match the selected adapter"
    );
    ensure!(
        snapshot
            .get("restore_latency_measured_as_physical_kv_hydration")
            .and_then(Value::as_bool)
            == Some(false),
        "calibration receipt claims an unmeasured restore latency"
    );

    let samples = receipt
        .get("context_samples")
        .and_then(Value::as_array)
        .filter(|samples| !samples.is_empty())
        .ok_or_else(|| anyhow::anyhow!("calibration has no context samples"))?;
    for sample in samples {
        ensure!(
            sample.get("status").and_then(Value::as_str) == Some("measured"),
            "calibration context sample is not measured"
        );
        ensure!(
            sample
                .get("prompt_tokens")
                .and_then(Value::as_u64)
                .is_some_and(|value| value > 0),
            "calibration prompt length is invalid"
        );
        ensure!(
            sample.get("decode_tokens").and_then(Value::as_u64) == Some(decode_tokens),
            "calibration decode length does not match the receipt"
        );
        validate_distribution(sample.get("prefill_micros"), measured_runs)?;
        validate_distribution(sample.get("decode_micros"), measured_runs)?;
    }
    Ok(())
}

fn bounded(receipt: &Value, field: &str, minimum: u64, maximum: u64) -> Result<u64> {
    let value = receipt
        .get(field)
        .and_then(Value::as_u64)
        .ok_or_else(|| anyhow::anyhow!("calibration field {field} is missing"))?;
    ensure!(
        (minimum..=maximum).contains(&value),
        "calibration field {field} is out of range"
    );
    Ok(value)
}

fn validate_distribution(distribution: Option<&Value>, measured_runs: u64) -> Result<()> {
    let distribution = distribution
        .and_then(Value::as_object)
        .ok_or_else(|| anyhow::anyhow!("calibration distribution is missing"))?;
    let samples = distribution
        .get("samples")
        .and_then(Value::as_array)
        .ok_or_else(|| anyhow::anyhow!("calibration distribution samples are missing"))?;
    ensure!(
        samples.len() as u64 == measured_runs,
        "calibration distribution does not contain the declared runs"
    );
    let mut values = samples
        .iter()
        .map(|sample| {
            sample.as_u64().ok_or_else(|| {
                anyhow::anyhow!("calibration distribution sample is not an unsigned integer")
            })
        })
        .collect::<Result<Vec<_>>>()?;
    values.sort_unstable();
    let len = values.len();
    ensure!(len > 0, "calibration distribution is empty");
    let p95_index = ((len * 95).saturating_add(99) / 100)
        .saturating_sub(1)
        .min(len - 1);
    let expected = [
        ("minimum", values[0]),
        ("median", values[len / 2]),
        ("p95", values[p95_index]),
        ("maximum", values[len - 1]),
    ];
    for (field, value) in expected {
        ensure!(
            distribution.get(field).and_then(Value::as_u64) == Some(value),
            "calibration distribution field {field} does not match its samples"
        );
    }
    Ok(())
}

fn is_sha256(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn receipt(schema: &str, bundle: &str) -> Value {
        json!({
            "project": "KV-SHEI",
            "product": "M-SLIM",
            "technical_namespace": "mslim",
            "schema": schema,
            "bundle": bundle,
            "source_revision": {
                "commit": crate::build_info::SOURCE_COMMIT,
                "tracked_files_modified_at_build": false
            },
            "adapter": "accelerator-runtime",
            "identity_digest": "b".repeat(64),
            "started_unix_seconds": 1,
            "load_micros": 1,
            "warmup_runs": 1,
            "measured_runs": 3,
            "decode_tokens_per_run": 8,
            "context_samples": [{
                "prompt_tokens": 1,
                "prefill_micros": {"samples": [1, 2, 3], "minimum": 1, "median": 2, "p95": 3, "maximum": 3},
                "prefill_tokens_per_second_median": 1.0,
                "decode_tokens": 8,
                "decode_micros": {"samples": [3, 4, 5], "minimum": 3, "median": 4, "p95": 5, "maximum": 5},
                "decode_tokens_per_second_median": 1.0,
                "snapshot_handle_bytes": 1,
                "status": "measured"
            }],
            "snapshot_contract": {
                "kind": PHYSICAL_COLDSTORE_SNAPSHOT_KIND,
                "physical_kv_persisted": true,
                "restore_latency_measured_as_physical_kv_hydration": false,
                "note": "logical replay only"
            },
            "validation_matrix_gate": "same-backend-and-kv-integrity-passed",
            "checks": ["inspect", "load"],
            "status": CALIBRATION_RECEIPT_STATUS
        })
    }

    #[test]
    fn accepts_only_the_canonical_v4_contract() {
        let bundle = "a".repeat(64);
        let canonical =
            validate_calibration_receipt(&receipt(CALIBRATION_RECEIPT_SCHEMA, &bundle), &bundle);
        assert_eq!(
            canonical.is_ok(),
            crate::build_info::current_build_is_clean()
        );
        for legacy in [
            "mslim.calibration_receipt/v1",
            "mslim.calibration_receipt/v2",
            "mslim.calibration_receipt/v3",
            "kvslim.calibration_receipt/v2",
        ] {
            assert!(validate_calibration_receipt(&receipt(legacy, &bundle), &bundle).is_err());
        }
    }

    #[test]
    fn rejects_cross_bundle_and_incomplete_evidence() {
        let bundle = "a".repeat(64);
        let mut value = receipt(CALIBRATION_RECEIPT_SCHEMA, &bundle);
        assert!(validate_calibration_receipt(&value, &"c".repeat(64)).is_err());
        value["source_revision"]["tracked_files_modified_at_build"] = json!(true);
        assert!(validate_calibration_receipt(&value, &bundle).is_err());
        value["source_revision"]["tracked_files_modified_at_build"] = json!(false);
        value["source_revision"]["commit"] = json!("0".repeat(40));
        assert!(validate_calibration_receipt(&value, &bundle).is_err());
        value["source_revision"]["commit"] = json!(crate::build_info::SOURCE_COMMIT);
        value["context_samples"] = json!([]);
        assert!(validate_calibration_receipt(&value, &bundle).is_err());
    }
}
